MultiLanguageSpellData['en'][1218316] = {name = "Corruption of the Aspects", additional_info = "1.5 sec cast\n[q]Summons and dismisses the Corruption of the Aspects. This mount changes depending on your Riding skill and location.\n[q]\"With N'Zoth's triumph, what started with Galakrond comes to fruition. With the Aspects gone, the corruption of their species is complete.\"\nVendor:\nTorie\nZone:\nDornogal\nCost:\n40000"}
MultiLanguageSpellData['en'][1218317] = {name = "Void-Crystal Panther", additional_info = "1.5 sec cast\n[q]Summons and dismisses a rideable Void-Crystal Panther.\n[q]\"Although many precious gems have been corrupted by void energies in horrific visions, Master Jewelcrafters can still utilize them to craft mighty panther steeds.\"\nProfession:\nJewelcrafting"}
