MultiLanguageSpellData['en'][1225311] = {name = "Entropic Consumption NOT USED", additional_info = "Unlimited range\nInstant\n[q]The crystal nexus unleashes a wave of entropy, absorbing 25 healing for1 min affecting all players."}
MultiLanguageSpellData['en'][1225312] = {name = "Amassing Voidlust", additional_info = "Instant\n[q]Harness the violent energy that permeates the Voidstorm, occasionally triggering a power suffusion of cosmic energy.\n\n When embraced, the energy erupts in a state called Voidlust.\n\nVoidlust\nBecome infused with ambient Void energies.\n\n Increase your chance to critically strike by 25%.\n Increase leech by 5%.\n Increase movement speed by 10%."}
MultiLanguageSpellData['en'][1225315] = {name = "Galactic Smash", additional_info = "Unlimited range\nInstant\n[q]Images of Salhadaar emerge alongside him to smash their targets with galactic force, applying Twilight Scar and inflicting 12142510 Cosmic damage to all players. Players farther from each target take less damage.\n\n Salhadaar's primary target is Starshattered . A Dark Star forms at each impact location."}
