MultiLanguageSpellData['en'][1225322] = {name = "Eversong Woods", additional_info = "Instant\n[q]Recommended Skill: 1\n\n Calm and serene waters make it an ideal location for Anglers to begin exploring what the depths have to offer.\n\n Pools found in this zone:\n - Sunwell Swarm\n - Bubbling Bloom\n - Bloom Swarm\n - Viscous Void\n - Careless Cargo\n - Lost Treasures\nProfession:\nFishing (1)"}
