MultiLanguageSpellData['en'][1226166] = {name = "Farstrider Rations", additional_info = "2 sec cast\nReagents:\nPractically Pork (2), Pouch of Spices , Thalassian Herbs\nOptional Reagents:\nSecret Ingredient (#480)\n[q]Recipe for 4 servings. Actual number of servings will vary based on cooking skill.\nProfession Trainer:\nMidnight Cooking (25)\nCost:\n120\n\n\n[q2]Use: Restores 5% of your maximum health every second over 20 sec. Must remain seated while eating.\n\n Well Fed\n If you spend at least 10 seconds eating, you will become Well Fed and gain ( 32 * .5) Mastery and ( 32 * .5) Haste for 1 hour.\n80"}
MultiLanguageSpellData['en'][1226167] = {name = "Hearty Food", additional_info = "2 sec cast\n[q]Condense 5 of your favorite meal to create a version that is sure to keep you satiated!\n\n Hearty food persists through death and is able to be shared amongst your Warband.\nProfession:\nCooking (35)"}
MultiLanguageSpellData['en'][1226168] = {name = "[q3]Quel'dorei Medley", additional_info = "2 sec cast 2\nReagents:\nEversong Trout (6), Tavern Fixings , Restored Songfish (4), Cooking Spirits , Thalassian Fillet (10), Petrified Root\nOptional Reagents:\nSecret Ingredient (#480)\n[q]Recipe for 2 servings. Actual number of servings will vary based on cooking skill.\nProfession Trainer:\nMidnight Cooking (85)\nCost:\n200\n\n[q3]Quel'dorei Medley\n\n[q2]Use: Place a Quel'dorei Medley for all players to enjoy!\n\nRestores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\n Well Fed\n If you spend at least 10 seconds eating, you will become Well Fed gaining 98 Stamina and ( 64 ) of your highest secondary stat for 1 hour.\n90"}
