MultiLanguageSpellData['en'][1229916] = {name = "[q3]Lucky Keychain", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Wild Magic , Evercore (5)\nOptional Reagents:\nProfession:\nRecycling\n\n[q3]Lucky Keychain\nOptional Crafting Reagent\n\n[q2]Provides the following property:\n\n Grants your equipment +1 Sparkle.\n[q]Usable with: Midnight recipes for most unembellished equipment.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1229917] = {name = "[q3]M3DDY, Travel-Sized", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSoul Sprocket , Aetherlume (3), Evercore (2)\nOptional Reagents:\nProfession:\nRecycling\n\n[q3]M3DDY, Travel-Sized\nOptional Crafting Reagent\n\n[q2]Provides the following property:\n\n A pocket-sized version of your buddy, M3DDY, that will revive you upon your untimely demise while outdoors.\n[q]Usable with: Midnight recipes for most unembellished equipment.\n[q]\"Created by players with the Engineering skill. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1229919] = {name = "[q3]Kinetic Ankle Primers", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSong Gear (2), Aetherlume (3), Evercore\nOptional Reagents:\nProfession:\nRecycling\n\n[q3]Kinetic Ankle Primers\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Prime your boots for engagement, launching you into the air and knocking up enemies on impact.\n\n Can only be used outdoors.\n[q]Usable with: Midnight Engineering Boots\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1229921] = {name = "[q3]HU5H, Nonchalant Pup", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Pure Void , Evercore (5)\nOptional Reagents:\nSpecialization:\nBits and Bots - Bots (30)\n\n[q3]HU5H, Nonchalant Pup\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Grants the user invisibility for 4-18 sec.\n\n Can only be used outdoors. Cannot be cast in combat.\n[q]Usable with: Midnight Engineering Crafted Equipment\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1229922] = {name = "[q3]B1P, Scorcher of Souls", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Wild Magic , Evercore (5)\nOptional Reagents:\nProfession:\nRecycling\n\n[q3]B1P, Scorcher of Souls\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Summons B1P, Scorcher of Souls to spray soul sparks on your enemies dealing Fire damage in a cone in front of you for 6 sec.\n[q]Usable with: Midnight Engineering Crafted Equipment\n[q]\"Summons Bip, Soul Scorcher. Created by players with the Engineering skill. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1229923] = {name = "[q2]Emergency Soul Link", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSoul Sprocket , Evercore\nOptional Reagents:\nProfession:\nRecycling\n\n[q2]Emergency Soul Link\n\n[q2]Use: Convince a dead ally that being alive is much more fun by catalyzing your whimsy, restoring them to life with 35% health and 10% mana. This always succeeds because it's objective truth.\n\n Castable in combat. Item quality affects cast time. Cannot be used by players higher than level 90. (10 Min Cooldown)\n68"}
MultiLanguageSpellData['en'][1229924] = {name = "[q3]M3DDY", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSong Gear , Soul Sprocket , Evercore\nOptional Reagents:\nSpecialization:\nBits and Bots - Bots\n\n[q3]M3DDY\n\n[q2]Use: Upon your untimely demise, summon M3DDY to... medicalize you and your raid back to life!\n\n Does not work on players whose spirits have been released and are above level 90.\n81"}
MultiLanguageSpellData['en'][1229926] = {name = "W-47CH D0G", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nProfession:\nRecycling\n\n\n[q2]Use: Deploy a W-47CH D0G unit that will calm the nerves of nearby party members, halting the expiration of Thalassian Flasks, Phials, and Well Fed effects.\n\n The pylon is extremely fragile and will detonate in the presence of violence.\n78"}
MultiLanguageSpellData['en'][1229927] = {name = "[q2]Curious Red Button", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nResourcefulness (#496)\nProfession:\nRecycling\n\n[q2]Curious Red Button\n\n[q2]Use: Deploy a particularly curious device.\n\n Lasts for 10 min. Must be deployed prior to combat. Only usable outdoors. (10 Min Cooldown)\n78"}
MultiLanguageSpellData['en'][1229928] = {name = "[q3]Wormhole Generator: Quel'Thalas", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nResourcefulness (#496)\nProfession:\nRecycling\n\n[q3]Wormhole Generator: Quel'Thalas\nToy\n\n[q2]Use: Open a wormhole that allows the user to quickly travel to a random Midnight location. (30 Min Cooldown)\n78\nRequiresMidnight Engineering\n(1)"}
