MultiLanguageSpellData['en'][1236332] = {name = "Druid Elune's Chosen 11.2 Class Set 2pc", additional_info = "[q]Balance\n Starfire damage increased by 15%. Gaining Astral Power with Starfire has a 40% chance to launch a Starsurge at a victim at 45% effectiveness.\n\nFeral, Guardian, Restoration\n Thrash damage increased by 20%. Thrash has a 40% chance to launch a Starsurge at a victim at 160% effectiveness.\n\n(100ms cooldown)"}
MultiLanguageSpellData['en'][1236333] = {name = "Druid Elune's Chosen 11.2 Class Set 4pc", additional_info = "[q]Balance\n On impact, Starsurges launched by Starfire split to up to 3 additional targets at 40% effectiveness and grant a stack of Gathering Moonlight. Casting Fury of Elune or Full Moon consumes Gathering Moonlight to increase your damage by 4% per stack for 12 sec.\n\nFeral, Guardian, Restoration\n On impact, Starsurges launched by Thrash split to up to 3 additional targets at 20% effectiveness and grant a stack of Gathering Moonlight. Casting Lunar Beam consumes Gathering Moonlight to increase your damage by 4% per stack for 12 sec."}
MultiLanguageSpellData['en'][1236334] = {name = "Druid Keeper of the Grove 11.2 Class Set 2pc", additional_info = "[q]Balance, Feral, Guardian\n Casting Celestial Alignment calls upon the assistance of a dryad for 10 sec that casts Starsurge at 360% effectiveness and Starfall at 800% effectiveness.\n\nRestoration\n Casting Incarnation: Tree of Life or Convoke the Spirits calls upon the assistance of a dryad for 5 sec that casts Tranquility at 50% effectiveness and instantly Regrowths your lowest health ally at 200% effectiveness."}
MultiLanguageSpellData['en'][1236336] = {name = "Druid Keeper of the Grove 11.2 Class Set 4pc", additional_info = "[q]Balance, Feral, Guardian\n When your Dryad fades, your next 2 Starsurges damage for an additional amount equal to 3% of your damage done while it was active and splash 10% of their damage onto nearby enemies, reduced beyond 5 targets.\n\nRestoration\n When your Dryad fades, your next 2 Swiftmends heal for an additional amount equal to 5% of your healing done while it was active and splash 25% of their healing onto nearby allies, reduced beyond 5 targets."}
MultiLanguageSpellData['en'][1236337] = {name = "Druid Wildstalker 11.2 Class Set 2pc", additional_info = "[q]Feral\n The rate at which Bloodseeker Vines grow is increased by 40%. Tiger's Fury causes Bloodseeker Vines to grow on up to 3 valid nearby enemies.\n\nBalance, Guardian, Restoration\n The rate at which Symbiotic Blooms grow is increased by 45%. Casting Regrowth with Clearcasting causes Symbiotic Blooms to grow on up to 2 valid nearby allies."}
MultiLanguageSpellData['en'][1236338] = {name = "Druid Wildstalker 11.2 Class Set 4pc", additional_info = "[q]Feral\n Bloodseeker Vines have a 20% chance to trigger Bursting Growth every 2 sec at 100% effectiveness. Each stack of Bloodseeker Vines on an enemy increases Bursting Growth damage taken by 40%.\n\nBalance, Guardian, Restoration\n Symbiotic Blooms have a 35% chance to trigger Bursting Growth every 2 sec at 100% effectiveness. Each stack of Symbiotic Blooms on an ally increases Bursting Growth healing taken by 30%."}
