MultiLanguageSpellData['en'][1236366] = {name = "Evoker Scalecommander 11.2 Class Set 2pc", additional_info = "[q]Augmentation\n While flying during Deep Breath and for 20 seconds after, you command a squadron of 2 Dracthyr who will attack your targets with Disintegrate and Pyre.\n\nDevastation, Preservation\n While flying during Deep Breath and for 10 seconds after, you command a squadron of 2 Dracthyr who will attack your targets with Disintegrate and Pyre."}
