MultiLanguageSpellData['en'][1236487] = {name = "[q3]Runed Brilliant Silver Rod", additional_info = "2 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nBrilliant Silver Ore (5), Eversinging Dust (20), Radiant Shard (5), Dawn Crystal (2), Silvermoon Weapon Wrap\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Reputable Rods\n\n[q3]Runed Brilliant Silver Rod\nBinds when equipped\nEnchanting Tool\n[q2]+ 45 Random Stat 1\n[q2]Equip: +18 Midnight Enchanting Skill\n78\nRequiresMidnight Enchanting\n(1)\n[q]\"Serves as a runed enchanting rod.\""}
MultiLanguageSpellData['en'][1236488] = {name = "[q4]Runed Dazzling Thorium Rod", additional_info = "2 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nFused Vitality (20), Dazzling Thorium (3), Eversinging Dust (30), Radiant Shard (10), Dawn Crystal (4), Silvermoon Weapon Wrap\nOptional Reagents:\nVendor:\nLyna\nZone:\nSilvermoon City\nCost:\n150\n\nVendor:\nLyrendal\nZone:\nSilvermoon City\nCost:\n150\n\n[q4]Runed Dazzling Thorium Rod\nBinds when picked up\nEnchanting Tool\n[q2]+ 48 Random Stat 1\n[q2]Equip: +18 Midnight Enchanting Skill\n78\nRequiresMidnight Enchanting\n(1)\n[q]\"Serves as a runed enchanting rod.\""}
MultiLanguageSpellData['en'][1236489] = {name = "[q3]Thalassian Spellweaver's Wand", additional_info = "2 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nEversinging Dust (15), Radiant Shard (3)\nOptional Reagents:\nProfession Trainer:\nMidnight Enchanting (40)\nCost:\n150\n\n[q3]Thalassian Spellweaver's Wand\nBinds when equipped\nRanged Wand\n3 - 6 Shadow Damage Speed 2.00\n(2.3 damage per second)\n+26 Intellect\n+7 Stamina\n[q2]+ 5 Random Stat 1\n[q2]+ 5 Random Stat 2\nDurability 90 / 90\n72"}
MultiLanguageSpellData['en'][1236490] = {name = "[q4]Magister's Grand Focus", additional_info = "2 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (10), Tormented Tantalum , Radiant Shard (20), Dawn Crystal , Silvermoon Weapon Wrap , Spark (#401) (2)\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Worthy Wands\n\n[q4]Magister's Grand Focus\nBinds when picked up\nRanged Wand\n3 - 6 Fire Damage Speed 2.00\n(2.3 damage per second)\n+26 Intellect\n+7 Stamina\n[q2]+ 5 Random Stat 1\n[q2]+ 5 Random Stat 2\nDurability 110 / 110\n70"}
MultiLanguageSpellData['en'][1236491] = {name = "[q2]Thalassian Phoenix Oil", additional_info = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (5), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Enchanting (20)\nCost:\n110\n\n[q2]Thalassian Phoenix Oil\n\n[q2]Use: Coat your weapon with Thalassian Phoenix Oil, increasing your Critical Strike and Haste by 13 for 120 min.\n\n Cannot be applied to items lower than level 120.\n78\n[q]\"The bottle contains what appears to be liquid fire and radiates warmth.\""}
MultiLanguageSpellData['en'][1236492] = {name = "[q2]Oil of Dawn", additional_info = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (5), Petrified Root (2), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Excellent Expendables\n\n[q2]Oil of Dawn\n\n[q2]Use: Coat your weapon with Oil of Dawn. Your healing spells and abilities have a chance to resonate with the oil and shield your target, absorbing the next 1503 damage they take.\n\n Lasts 120 min.\n\n Cannot be applied to items lower than level 120.\n78\n[q]\"A vial of holy oil blessed by the Sunwell.\""}
MultiLanguageSpellData['en'][1236493] = {name = "[q2]Smuggler's Enchanted Edge", additional_info = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Primal Energy (5), Petrified Root (2), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nDrop:\nLithiel Cinderfury\nZone:\nMurder Row\n\n[q2]Smuggler's Enchanted Edge\n\n[q2]Use: Coat your weapon with Smuggler's Enchanted Edge. This oil has a chance to activate whenever you deal damage, inflicting ( 1 * 1002 ) Arcane damage to the target.\n\n Lasts 120 min.\n\n Cannot be applied to items lower than level 120.\n78\n[q]\"More of a magical toxic sludge than an oil, really.\""}
