MultiLanguageSpellData['en'][1243174] = {name = "Blessing: Victor's Presence", additional_info = "[q]Akil'zon, Loa of Victory\n Mot'amra, Loa of Pestilence\n\n The loas of Victory and Pestilence bless you with a 15% chance to Stun your enemy for 3 sec.\n\n Does not work on players.\n Only active while in Zul'Aman."}
