MultiLanguageSpellData['en'][1243190] = {name = "Blessing: The Cunning Hunt", additional_info = "[q]Halazzi, Loa of the Hunt\n Shadra, Loa of Subterfuge\n\n While in combat, the loas of the Hunt and Subterfuge increase your critical strike chance by 1% every 1 second up to 15%. Decreases while out of combat.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243191] = {name = "Blessing: Guide of the Harvest", additional_info = "[q]Halazzi, Loa of the Hunt\n Dundun, Loa of Abundance\n\n The loas of the Hunt and Abundance bless your Professions Gathering with a 15% chance to summon a Visage of Dundun every time you successfully harvest using Mining, Herbalism, Skinning, or Fishing."}
MultiLanguageSpellData['en'][1243192] = {name = "Blessing: Predator's Gamble", additional_info = "[q]Halazzi, Loa of the Hunt\n Puul, Loa of Peril\n\n Through the loas of the Hunt and Peril, you have a 25% chance on hit to deal 100% more damage.\n\n But you also have a 25% chance on hit to deal -50% less damage.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243193] = {name = "Blessing: Patient Hunter", additional_info = "[q]Halazzi, Loa of the Hunt\n Oe, Loa of Growth\n\n Through the loas of the Hunt and Forests, you gain a 5% chance for your attack to deal 500% damage.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243194] = {name = "Blessing: Flame of Vitality", additional_info = "[q]Jan'alai, Loa of Fire\n Kulzi, Loa of Medicine\n\n The loas of Fire and Medicine increase your Spell Power by 20% while your health is above 90%.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243195] = {name = "Blessing: Flowing Flame", additional_info = "[q]Jan'alai, Loa of Fire\n Filo, Loa of Children\n\n The loas of Fire and Childhood bless you with a 2% increase to Intelligence with every successful spell cast for 10 sec. Stacks up to 10 times.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243196] = {name = "Blessing: Buoyant Flame", additional_info = "[q]Jan'alai, Loa of Fire\n Pahk, Loa of the Depths\n\n The loas of Fire and the Depths bless you with Waterwalking.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243197] = {name = "Blessing: Ensorcelling Flame", additional_info = "[q]Jan'alai, Loa of Fire\n Mot'amra, Loa of Pestilence\n\n The loas of Fire and Pestilence bless you with a 5% chance to Charm your enemy for 5 sec, forcing them to fight other hostile foes on your behalf.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243198] = {name = "Blessing: Packpeddle of Fire", additional_info = "[q]Jan'alai, Loa of Fire\n Wila'ma, Loa of Travelers\n\n The loas of Fire and Travelers have stationed Packpeddlers throughout the land for your use.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243200] = {name = "Blessing: Creeping Flame", additional_info = "[q]Jan'alai, Loa of Fire\n Shadra, Loa of Subterfuge\n\n While in combat, the loas of Fire and Subterfuge increase your Spell Power by 1% every 1 second up to 25%. Decreases while out of combat.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243201] = {name = "Blessing: Harvest Haste", additional_info = "[q]Jan'alai, Loa of Fire\n Dundun, Loa of Abundance\n\n The loas of the Hunt and Abundance increase your Movement Speed by 100% for 5 sec whenever you gather reagents via Mining, Herbalism, Skinning, or Fishing.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243202] = {name = "Blessing: Ravenous Glass", additional_info = "[q]Jan'alai, Loa of Fire\n Puul, Loa of Peril\n\n Through the loas of Victory and Peril, you gain 100% Spell Power\n\n But you will also receive 100% more damage from all sources.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243203] = {name = "Blessing: Everthrive Flame", additional_info = "[q]Jan'alai, Loa of Fire\n Oe, Loa of Growth\n\n Through the loas of Fire and Growth, you gain a 15% increase to Intelligence.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243204] = {name = "Blessing: War of Attrition", additional_info = "[q]Nalorakk, Loa of War\n Kulzi, Loa of Medicine\n\n Through the loas of War and of Medicine, you are healed 50% whenever your health is brought below 15%.\n\n Cannot occur more than once every 10 min.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243205] = {name = "Blessing: War Against Threats", additional_info = "[q]Nalorakk, Loa of War\n Filo, Loa of Children\n\n When Health is below 50%, the loas of War and Children summon a Grand Kapara Guard to fight with you for 2 min.\n\n Only usable in Zul'Aman."}
MultiLanguageSpellData['en'][1243206] = {name = "Blessing: War on the Currents", additional_info = "[q]Nalorakk, Loa of War\n Pahk, Loa of the Depths\n\n The loas of War and the Depths grant you the ability to walk upon any body of water's floor.\n\n Only usable in Zul'Aman."}
MultiLanguageSpellData['en'][1243207] = {name = "Blessing: War-Spoiled", additional_info = "[q]Nalorakk, Loa of War\n Mot'amra, Loa of Pestilence\n\n The loas of War and Pestilence bless you with a 15% chance to pierce a target's armor, increasing Physical damage taken by 30% for 10 sec. This effect stacks up to 5 charges.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243208] = {name = "Blessing: Packpeddle of War", additional_info = "[q]Nalorakk, Loa of War\n Wila'ma, Loa of Travelers\n\n The loas of War and Travelers have stationed Packpeddlers throughout the land for your use.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243209] = {name = "Blessing: Wartime Preparations", additional_info = "[q]Nalorakk, Loa of War\n Shadra, Loa of Subterfuge\n\n While in combat, the loas of War and Subterfuge increase your Health by 1% and Armor by 2% every 1 second (Maximum of 25 stacks). Decreases while out of combat.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243210] = {name = "Blessing: Abundance Permanence", additional_info = "[q]Nalorakk, Loa of War\n Dundun, Loa of Abundance\n\n Whenever you gather reagents via Mining, Herbalism, Skinning, or Fishing, the Loas of War and Abundance heal you by 15% and reduce damage taken by 50% until you're damaged next.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243211] = {name = "Blessing: Reckless Feast", additional_info = "[q]Nalorakk, Loa of War\n Puul, Loa of Peril\n\n Through the loas of War and Peril, you gain 25% Leech.\n\n But you also take 25% more damage from all sources.\n\n Only active while in Zul'Aman."}
MultiLanguageSpellData['en'][1243213] = {name = "Blessing: Command Experience", additional_info = "[q]Nalorakk, Loa of War\n Oe, Loa of Growth\n\n Through the loas of War and Growth, you gain 10% more Strength and Stamina.\n\n Only active while in Zul'Aman."}
