MultiLanguageSpellData['en'][1251265] = {name = "Arcberry Manasaber", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Named for their resemblance to the bright berries made into arcwine, these proud cats have a keen awareness of the ley lines that travel beneath them.\"\nWorld Event:\nWoW Remix: Legion"}
