MultiLanguageSpellData['en'][1251279] = {name = "Fel-Scarred Mana Ray", additional_info = "1.5 sec cast\n[q]Summons and dismisses a Fel-Scarred Mana Ray. This mount changes depending on your Riding skill and location.\n[q]\"Surviving on Argus is not an easy task. Its leathery hide scarred by fel corruption, this mana ray is prone to fits of aggression, moreso than usual.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageSpellData['en'][1251281] = {name = "Bloodtooth Mana Ray", additional_info = "1.5 sec cast\n[q]Summons and dismisses a Bloodtooth Mana Ray. This mount changes depending on your Riding skill and location.\n[q]\"The shattering of Argus drove this breed of mana ray to bloodthirst. It now subsists on the corrupted blood of any creatures it can sink its many teeth into.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageSpellData['en'][1251282] = {name = "Activate", additional_info = nil}
MultiLanguageSpellData['en'][1251283] = {name = "Albino Mana Ray", additional_info = "1.5 sec cast\n[q]Summons and dismisses a Albino Mana Ray. This mount changes depending on your Riding skill and location.\n[q]\"The shattering of Argus caused the mana rays to mutate and adapt to their surroundings. Some of them abandoned their pigments in favor of strengthening their senses.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageSpellData['en'][1251284] = {name = "Luminous Mana Ray", additional_info = "1.5 sec cast\n[q]Summons and dismisses a Luminous Mana Ray. This mount changes depending on your Riding skill and location.\n[q]\"Mana rays can emit a bright glow to lure in prey.\"\nWorld Event:\nWoW Remix: Legion"}
