MultiLanguageSpellData['en'][1251295] = {name = "Twilight Courser", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"To evade predators, this courser dims its horn while hiding and flashes with dazzling radiance when provoked.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageSpellData['en'][1251297] = {name = "Golden Sunrunner", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This free spirit enjoys long trots on the beach and frolicking through varicolored floral fields.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageSpellData['en'][1251298] = {name = "Turquoise Courser", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Named for its uniquely colored eyes that seem to pierce your soul, the turquoise courser shows more intelligence than her dreamrunner cousins and is known to be an excellent judge of character.\"\nWorld Event:\nWoW Remix: Legion"}
