MultiLanguageSpellData['en'][1257796] = {name = "[q3]Silvermoon Parade", additional_info = "2 sec cast 2\nReagents:\nLynxfish (4), Tavern Fixings , Arcane Wyrmfish (4), Cooking Spirits , Practically Pork (10), Petrified Root\nOptional Reagents:\nSecret Ingredient (#480)\n[q]Recipe for 2 servings. Actual number of servings will vary based on cooking skill.\nProfession Trainer:\nMidnight Cooking (85)\nCost:\n200\n\n[q3]Silvermoon Parade\n\n[q2]Use: Place a Silvermoon Parade for all players to enjoy!\n\nRestores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\n Well Fed\n If you spend at least 10 seconds eating, you will become Well Fed gaining 98 Stamina and 50 primary stat for 1 hour.\n90"}
MultiLanguageSpellData['en'][1257798] = {name = "Trap: Void Sphere", additional_info = "{Instant} {8 sec cooldown}\n[q]Cast Time: 2.5 seconds.\n Trap Cooldown: 8 seconds.\n Can be cast while moving.\n\n Creates a Void Sphere that persists for 30 sec. The sphere behaves differently for Hiders and Seekers.\n\nHiders who make contact with the sphere are propelled forwards up to 30 yards.\n\nSeekers who make contact with the sphere are repelled backwards up to 20 yards.\n\nDon't worry--the cold emptiness of the void lasts for but a moment. Soon, your guts will be be wrenched in one direction or another, and it will all be over before you know it."}
